TLM.f("Sancti/07-16",{"officium":"Beatæ Mariæ Virginis de Monte Carmelo","rule":["ex C11;","Gloria","CredoDA","Prefatio=Maria=Commemoratione;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Gaudeamus omnes in Domino diem festum celebrantes sub honore beatae Mariæ Virginis: de cujus assumptione qaudent, angeli, et collaudant Filium Dei."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudeamus omnes in Domino diem festum celebrantes sub honore beatae Mariæ Virginis: de cujus assumptione qaudent, angeli, et collaudant Filium Dei."}],"Oratio":[{"k":"text","la":"Deus, qui beatíssimæ semper Vírginis et Genetrícis tuæ Maríæ singulári título Carméli órdinem decorásti: concéde propítius; ut, cujus hódie Commemoratiónem sollémni celebrámus offício, ejus muníti præsídiis, ad gáudia sempitérna perveníre mereámur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:23-31"},{"k":"text","la":"Ego quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Felix es, sacra Virgo María, et omni laude digníssima: quia ex te ortus est sol justítiæ, Christus, Deus noster.","mark":"V"},{"k":"sep"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Per te, Dei Génetrix, nobis est vita pérdita data: quæ de cœlo suscepísti prolem, et mundo genuísti Salvatórem. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 11:27-28"},{"k":"text","la":"In illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud."}],"Offertorium":[{"k":"ref","la":"Jer 18:20"},{"k":"text","la":"Recordáre, Virgo Mater, in conspéctu Dei, ut loquáris pro nobis bona, et ut avértat indignatiónem suam a nobis."}],"Secreta":[{"k":"text","la":"Sanctífica, Dómine, quǽsumus, obláta libámina: et, beátæ Dei Genetrícis Maríæ salubérrima intercessióne, nobis salutária fore concéde."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"text","la":"Regína mundi digníssima, María Virgo perpétua, intercéde pro nostra pace et salúte, quæ genuísti Christum Dóminum, Salvatórem ómnium."}],"Postcommunio":[{"k":"text","la":"Adjuvet nos, quǽsumus, Dómine, gloriósæ tuæ Genetrícis sempérque Vírginis Maríæ intercéssio veneránda: ut, quos perpétuis cumulávit benefíciis, a cunctis perículis absolútos, sua fáciat pietáte concórdes:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"df93f7d29ce164e4":{"t":"<i>Pomolimo se</i>.\nBože, koji si karmelski red ukrasio posebnim nazivom blažene vazda Djevice i Majke svoje Marije, daj milostivo, da osigurani zaštitom one koje spomen danas službom slavimo, zavrijedimo doći u vječnu radost:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"fe56861c1752e595":{"t":"Posveti, molimo, Gospodine, prikazane darove i daj da nam budu spasonosni po moćnom zagovoru blažene Bogorodice Marije.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"5d6d36d3129cde5f":{"t":"<i>Pomolimo se</i>.\nNeka nas pomaže, molimo, Gospodine, časni zagovor slavne tvoje Majke i vazda Djevice Marije, da nas oslobođene od pogibelji po svojoj dobroti složi ona koja nas je obasula vječnim dobročinstvima.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
